 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op4(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@RequestParam(required=false) @Pattern(regexp="[A-Za-z0-9_-]{6,100}") String gatewaySessionId){return ApiResponse.ok("Reconcile Razorpay order and captured payment without recreating it",payments.reconcile(id,gatewaySessionId));}
 @GetMapping("/api/v1/admin/refunds") @PreAuthorize("hasAuthority('REFUND_APPROVE')") @Operation(summary="List refund requests",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.payment.dto.PaymentResponses.RefundView>> op5(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List refund requests",reads.refunds(page,size));}
 @PutMapping("/api/v1/admin/refunds/{id}/approve") @PreAuthorize("hasAuthority('REFUND_APPROVE')") @Operation(summary="Refund approve",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.RefundView> op6(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Refund approve",service.approve(p.userId(),id,q,true));}
 @PutMapping("/api/v1/admin/refunds/{id}/reject") @PreAuthorize("hasAuthority('REFUND_APPROVE')") @Operation(summary="Refund reject",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.RefundView> op7(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Refund reject",service.approve(p.userId(),id,q,false));}
 @PostMapping("/api/v1/admin/refunds/{id}/process") @PreAuthorize("hasAuthority('REFUND_APPROVE')") @Operation(summary="Dispatch an approved refund once",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.RefundView> op8(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Dispatch an approved refund once",service.process(p.userId(),id));}
 @PostMapping("/api/v1/admin/refunds/{id}/reconcile") @PreAuthorize("hasAuthority('REFUND_APPROVE')") @Operation(summary="Reconcile refund using authenticated provider lookup",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.RefundView> op9(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@RequestParam @Pattern(regexp="[0-9]{1,32}") String gatewayRefundId){return ApiResponse.ok("Reconcile refund using authenticated provider lookup",service.reconcileRefund(p.userId(),id,gatewayRefundId));}
 @PutMapping("/api/v1/owner/restaurants/{restaurantId}/refunds/{id}/confirm-cash") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_PAYMENT_MANAGE')") @Operation(summary="Confirm approved cash refund actually returned",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.RefundView> op10(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q,@RequestParam @Pattern(regexp="[A-Za-z0-9_-]{8,80}") String receipt){return ApiResponse.ok("Confirm approved cash refund actually returned",mapper.refund(transactions.cashRefund(p.userId(),restaurantId,id,q,receipt)));}
 @GetMapping("/api/v1/admin/commission-rules") @PreAuthorize("hasAuthority('COMMISSION_MANAGE')") @Operation(summary="List commission rules",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<List<com.bookeat.payment.dto.PaymentResponses.CommissionView>> op11(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("List commission rules",reads.commissions());}
 @PostMapping("/api/v1/admin/commission-rules") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @PreAuthorize("hasAuthority('COMMISSION_MANAGE')") @Operation(summary="Create effective commission rule",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.CommissionView> op12(@AuthenticationPrincipal AppPrincipal p,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Commission q){return ApiResponse.ok("Create effective commission rule",mapper.commission(transactions.commission(p.userId(),q)));}
 @PutMapping("/api/v1/admin/commission-rules/{id}/disable") @PreAuthorize("hasAuthority('COMMISSION_MANAGE')") @Operation(summary="Disable commission rule for future payments",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.CommissionView> op13(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Disable commission rule for future payments",mapper.commission(transactions.disableCommission(p.userId(),id,q)));}
 @PostMapping("/api/v1/admin/settlements") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @PreAuthorize("hasAuthority('SETTLEMENT_MANAGE')") @Operation(summary="Create non-duplicated settlement ledger batch",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.SettlementView> op14(@AuthenticationPrincipal AppPrincipal p,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.SettlementCreate q){return ApiResponse.ok("Create non-duplicated settlement ledger batch",service.createSettlement(p.userId(),key,q));}
 @GetMapping("/api/v1/admin/settlements") @PreAuthorize("hasAuthority('SETTLEMENT_MANAGE')") @Operation(summary="List settlement batches",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.payment.dto.PaymentResponses.SettlementView>> op15(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List settlement batches",reads.settlements(p.userId(),null,page,size));}
 @PutMapping("/api/v1/admin/settlements/{id}/status") @PreAuthorize("hasAuthority('SETTLEMENT_MANAGE')") @Operation(summary="Record settlement processing and external transfer reference",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.SettlementView> op16(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.SettlementAction q){return ApiResponse.ok("Record settlement processing and external transfer reference",service.settlementAction(p.userId(),id,q));}
 @GetMapping("/api/v1/owner/restaurants/{restaurantId}/settlements") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_PAYMENT_VIEW')") @Operation(summary="List owned restaurant settlement batches",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.payment.dto.PaymentResponses.SettlementView>> op17(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List owned restaurant settlement batches",reads.settlements(p.userId(),restaurantId,page,size));}
